MCAR_RATE = 0.04         # cells lost at random, whatever their value
BATCH_SHIFT, BATCH_SD, BATCH_SCALE = 0.3, 0.5, 1.3   # batch 1 vs batch 0: mean shift, per-protein shift, noise factor
